<template>
	<view class="zuti">
		<view class="btn-box">
			<view class="del-tex">
				账号管理
			</view>
			<view class="del-btn" @click="back">
				返回
			</view>
		</view>
		<view class="account-box" v-for="(item,index) in list" :key="index">
			<view class="account-desc">{{item.courseTitle}}</view>
			<view class="acc-label">登录账号</view>
			<view class="acc-item">
				<text class="iconfont icon-zhanghaoguanli1"></text>
				<text class="acc-value">{{item.account}}</text>
				<text class="acc-btn" @click="copy(item.account)">复制</text>
			</view>
			<view class="acc-label">登录密码</view>
			<view class="acc-item">
				<text class="iconfont icon-mima3"></text>
				<text class="acc-value">{{item.password}}</text>
				<text class="acc-btn" @click="copy(item.password)">复制</text>
			</view>
		</view>

		<!-- 		加载提示 -->
		<view class="loading" v-if="showLoading">
			<text style="--i:1">加</text>
			<text style="--i:2">载</text>
			<text style="--i:3">中</text>
			<text style="--i:4">.</text>
			<text style="--i:5">.</text>
			<text style="--i:6">.</text>
		</view>
		<view class="end" v-if="showNone">暂无更多...</view>
	</view>
</template>
<script>
	import {
		loaded,
		loading,
		toast,
		redirectTo,
		navigateTo,
		navigateBack,
		copyText
	} from '@/utils/index.js';
	import {
		img_PATH
	} from '@/config';
	import {
		queryAssignedAccounts
	} from '@/api/index.js'
	export default {
		data() {
			return {
				imgurl: img_PATH,
				CustomBar: this.CustomBar,
				showLoading: false,
				showNone: false,
				page: 1,
				limit: 20,
				list: []
			};
		},
		computed: {

		},
		components: {

		},
		onLoad() {

		},
		created() {
			this.getList()
		},
		// 触底的事件
		onReachBottom() {
			this.getList()
		},
		methods: {
			async getList() {
				this.showNone = false
				this.showLoading = true
				let _data = await queryAssignedAccounts(this.page, this.limit);
				if (_data.code == 200) {
					if (_data.data.length == 0) {
						this.showLoading = false
						this.showNone = true
						return
					}
					this.page++
					this.showLoading = false
					this.list = [...this.list, ..._data.data]
				}
			},
			back() {
				navigateBack()
			},
			copy(text) {
				copyText(text)
			},
			to(path) {
				navigateTo(path)
			},
		},

	}
</script>

<style scoped lang="scss">
	.zuti {
		min-height: 100vh;
		width: 100%;
		padding: 30rpx 25rpx;
		background-color: #f7f7f7;
		padding-top: 120rpx;

		.btn-box {
			width: 100%;
			height: 90rpx;
			background: #ffffff;
			border-bottom: 1rpx solid #eeeeee;
			display: flex;
			justify-content: space-between;
			align-items: center;
			padding: 0 30rpx;
			position: fixed;
			top: 0;
			left: 0;
			z-index: 1;

			.del-btn {
				width: 100rpx;
				height: 46rpx;
				background-image: linear-gradient(90deg,
						#80b9f6 0%,
						#1f89f6 100%);
				border-radius: 10rpx;
				text-align: center;
				line-height: 46rpx;
				color: #ffffff;
				font-size: 26rpx;
			}

			.del-tex {
				font-size: 30rpx;
				color: #666666;
				font-weight: bold;
			}
		}

		.account-box {
			width: 100%;
			background-color: #ffffff;
			border-radius: 20rpx;
			padding: 30rpx;
			margin-bottom: 25rpx;

			.acc-item {
				width: 100%;
				height: 79rpx;
				background-color: #f8f9fc;
				border-radius: 16rpx;
				border: solid 2rpx #dedfe1;
				display: flex;
				justify-content: space-between;
				align-items: center;
				padding-left: 24rpx;
				padding-right: 15rpx;

				.acc-btn {
					width: 101rpx;
					height: 50rpx;
					background-image: linear-gradient(90deg,
							#61b7ff 0%,
							#2c90f7 100%);
					border-radius: 6rpx;
					font-size: 28rpx;
					color: #ffffff;
					text-align: center;
					line-height: 50rpx;
				}

				.acc-value {
					flex: 1;
					font-size: 30rpx;
					color: #2b2e48;
					padding: 0 22rpx;
				}

				.iconfont {
					font-size: 42rpx;
					color: #888c99;
				}
			}

			.acc-label {
				width: 100%;
				font-size: 28rpx;
				color: #888c99;
				padding-top: 35rpx;
				padding-bottom: 20rpx;
			}

			.account-desc {
				width: 100%;
				text-align: center;
				font-size: 28rpx;
				color: #1f89f6;
				padding-top: 15rpx;
				font-weight: bold;
				line-height: 28rpx;
			}
		}
	}
</style>